// Provided (default) trait methods for classes that cannot `extends` their trait's `<Trait>_provided` base class (lane
// interp-miri-reconcile, miri-contract review M7). Our own code, not a port.
//
// PORTING §8 puts a trait's provided methods in a `<Trait>_provided` helper class that implementors extend. A class
// generated by tools/codegen (`MiriMachine`, `MonoHashMap`) has no `extends`, so its module copies the defaults onto the
// prototype instead: `provide_defaults(Target.prototype, Trait_provided.prototype, overridden)`, where `overridden` lists
// the provided methods the upstream impl defines itself (those are the impl's: ported, or an `unported` stub until then).
// Every other provided method is copied, so a hook the upstream impl does not override behaves as the default.
//
// Strict, like src/rust_ts/miri_stub.ts: a name in `overridden` that is not a provided method of the base (a typo, or the
// trait changed) is an error, and so is a copied name that the target already defines (the impl ported an override but it
// is missing from `overridden`): a default never silently replaces an impl's method, nor the reverse.

/** Copies the provided methods of `base` (a `<Trait>_provided` prototype) onto `target` (a prototype), except `overridden`. */
export function provide_defaults(target: object, base: object, overridden: readonly string[]): void {
  const provided = Object.getOwnPropertyNames(base).filter((n) => n !== "constructor");
  for (const name of overridden) {
    if (!provided.includes(name)) throw new Error(`provide_defaults: \`${name}\` is not a provided method of the trait`);
  }
  for (const name of provided) {
    if (overridden.includes(name)) continue;
    if (Object.prototype.hasOwnProperty.call(target, name)) {
      throw new Error(`provide_defaults: \`${name}\` is already defined on the target (list it in \`overridden\`)`);
    }
    const desc = Object.getOwnPropertyDescriptor(base, name);
    if (desc !== undefined) Object.defineProperty(target, name, desc);
  }
}

/**
 * Defines the associated items of a trait impl (the impls of its associated types, its consts) as read-only prototype
 * members of `target`. `lazy` items are getters (values of other modules, read on use, not at load: init order).
 */
export function define_assoc(target: object, items: Record<string, unknown>, lazy: Record<string, () => unknown> = {}): void {
  const define = (name: string, desc: PropertyDescriptor): void => {
    if (Object.prototype.hasOwnProperty.call(target, name)) throw new Error(`define_assoc: \`${name}\` is already defined on the target`);
    Object.defineProperty(target, name, { ...desc, configurable: true, enumerable: false });
  };
  for (const [name, value] of Object.entries(items)) define(name, { value, writable: false });
  for (const [name, get] of Object.entries(lazy)) define(name, { get });
}
